# -*- coding: utf-8 -*-
from itbase import *

IT01 = F('XX', 'Tawhid: rububiyya, uluhiyya y atributos', 'Tawhid',
 'Ibn Taymiyya sostiene que el tawhid que predicaron los profetas es, ante todo, adorar a Dios solo (uluhiyya); reconocerlo como creador (rububiyya) no basta, porque los politeístas árabes también lo reconocían.',
 'Sus propias frases sobre las «clases» de tawhid, y lo que NO dice: las tres etiquetas juntas, como tres clases de tawhid con esos nombres, no aparecen así en los textos que se revisaron.',
 ['maj', 'isf', 'tadm'], FOOT,
 [
  Q('T1-MF-V10-262', es='«[…] muchos de ellos creen que el tawhid obligatorio es [[k:reconocer y creer que Dios es el creador de todo y su Señor]], y no distinguen entre el reconocimiento del tawhid de la rububiyya, [[k:que reconocieron los politeístas árabes]], y el tawhid de la uluhiyya al que los llamó el Mensajero de Dios, ni reúnen el tawhid de palabra con el de obra.»',
     theme=['T'], clar='Habla en su propia voz y critica a muchos musulmanes (los teólogos del kalam y quienes los siguen): reducen el tawhid a confesar que Dios es el creador. Para él, eso es lo que también admitían los politeístas de la Meca; lo que hace falta es la adoración exclusiva («tawhid de la uluhiyya») y que la palabra vaya con la obra.'),
  Q('T1-SI-V1-106', es='«El discurso sobre el tawhid comprende [[k:tres clases]]: la primera, el discurso sobre los atributos; la segunda, el tawhid de la rububiyya, es decir, que Dios es el creador de todo; la tercera, [[k:el tawhid de la uluhiyya, que es adorar a Dios solo, sin asociado]].»',
     theme=['T'], clar='Es su lista de tres temas dentro del tawhid. Ojo con la etiqueta: el primero no se llama «tawhid de los nombres y atributos» sino «el discurso sobre los atributos». La división en dos (rububiyya y uluhiyya) sí aparece en muchas obras suyas (Majmu\' al-Fatawa, vols. 10, 11, 14 y 22; Dar\' ta\'arud, vol. 9); la fórmula de tres «tawhid» con exactamente esos tres nombres no la encontró el investigador en sus textos, solo en notas editoriales.'),
  Q('T11-T01', es='«La generalidad de los teólogos que establecen el tawhid en los libros del kalam y de la especulación [[k:no pasan de dividirlo en tres clases]]: dicen que es uno en su esencia, sin división; uno en sus atributos, sin semejante; y uno en sus actos, sin asociado.»',
     theme=['T'], clar='Aquí NO habla en nombre propio: informa de la división tripartita de los teólogos del kalam (esencia, atributos, actos) para criticarla a continuación. No hay que confundirla con su esquema (rububiyya, uluhiyya, atributos). Quién usó antes que él los términos rububiyya y uluhiyya no lo he comprobado: lo que sí muestran sus textos es que él los pone en el centro.'),
 ])

IT02 = F('XX', 'Atributos de Dios y la Palabra de Dios', 'Tawhid',
 'Ibn Taymiyya afirma los atributos de Dios tal como los dicen el Corán y la Sunna, sin cambiarles el sentido ni preguntar «cómo»; entre ellos, el habla de Dios, que es eterna e increada.',
 'Es la base de su teología de los atributos y la que luego aplica al debate con los cristianos (la «Palabra» de Dios).',
 ['wasit', 'maj'], FOOT,
 [
  SP('wasit', 'ومن الإيمان بالله الإيمان بما وصف به نفسه', 'وهو السميع البصير',
     es='«Parte de la fe en Dios es creer en lo que Él mismo dijo de sí en su Libro y en lo que dijo de Él su Mensajero, Muhammad, [[k:sin distorsión ni negación, sin «cómo» ni comparación]]: creen que Dios —glorificado sea— «nada es como Él», y que Él es «el Oyente, el Vidente».»',
     theme=['T'], clar='Es su fórmula programática: no cambiar el sentido de los textos (tahrif), no vaciarlos de contenido (ta\'til), no preguntar el modo (takyif) ni comparar con las criaturas (tamthil). Cita Corán 42:11.'),
  Q('T2-07', es='«La palabra de Dios no está separada de Dios. No es algo aparte de Él, ni distinto de Él, ni tampoco es Él mismo: [[k:es un atributo de su esencia]], como su ciencia, que es un atributo de su esencia. Nuestro Señor siempre fue conocedor y siempre lo será; [[k:siempre fue hablante y siempre habla]].»',
     theme=['T'], clar='Afirma que el habla de Dios es un atributo eterno que subsiste en Dios. La fórmula «ni él ni otra cosa» la matiza en otros lugares (en Majmu\' 17/160 llama «error» a afirmar a la vez ambos negativos como un «tercer caso»); aquí solo se muestra su afirmación del habla eterna.'),
  Q('T2-08', es='«[…] que [[k:todo el Corán es palabra de Dios, sus letras y sus significados]]; nada de ello es palabra de otro, sino que Él lo hizo descender sobre su Mensajero. El Corán no es el nombre de un mero significado ni de meras letras, sino [[k:de ambos juntos]].»',
     theme=['T'], start='أن القرآن جميعه كلام الله', clar='Es el final de una frase en la que atribuye esta postura a los antepasados (el imán Ahmad, al-Bujari y otros). Lectura (mía) para el debate con los cristianos: él acepta un «habla» de Dios eterna que subsiste en Dios; lo que rechaza es que esa Palabra sea una persona (véase IT10 e IT11).'),
 ])

IT03 = F('XX', 'Composición y simplicidad divina', 'Tawhid',
 'Ibn Taymiyya rechaza el argumento de los filósofos según el cual tener atributos distintos sería «composición» en Dios: para él, la esencia con atributos inherentes es tawhid.',
 'Importa porque la objeción «Dios es simple, no puede tener partes ni personas» no es suya: él acepta atributos reales y distintos en Dios.',
 ['tadm', 'jawab', 'isf'], FOOT,
 [
  Q('T2-11', es='«Se les dice: que la esencia esté descrita con atributos que le son inherentes [[k:es tawhid en realidad y no una composición imposible]]. Pues es sabido por la razón clara que ser «conocedor» no significa lo mismo que ser «poderoso», y que la esencia misma no es lo mismo que ser conocedora y poderosa.»',
     theme=['T'], clar='Responde a los teólogos y filósofos que negaban los atributos para salvar la «unicidad» entendida como simplicidad total. Distingue en Dios la esencia, la ciencia y el poder como significados distintos.'),
  Q('T2-12', es='«En cuanto a que la esencia esté descrita con atributos que subsisten en ella, esto es lo que conocen los sensatos en general, pero [[k:no lo llaman composición]]; y quien lo llama composición, su disputa es solo de palabras y no afecta a lo que se sabe por las pruebas de la revelación y de la razón.»',
     theme=['T'], clar='Está en al-Jawab al-Sahih, dentro del debate con los cristianos: para él la discusión sobre si «composición» es la palabra adecuada es verbal, no de fondo.'),
  Q('T2-13', es='«Primero: se dice que lo que afirma quien dice «esto implica que necesita aquello de lo que está compuesto, y eso contradice la necesidad de existir» [[k:no se admite]]; pues lo máximo que implica es que aquello de lo que está compuesto sea una de sus partes, y decir que lo compuesto necesita su parte [[k:no es más grave que decir que necesita su todo]].»',
     theme=['T'], clar='Replica al argumento filosófico de que lo compuesto depende de sus partes y, por tanto, no puede ser el Ser Necesario. Lectura (mía): como no usa la simplicidad divina contra los cristianos, sus objeciones a la Trinidad tienen que apoyarse en otros argumentos (atributos que no son personas, contradicción 3 = 1, etc.).'),
 ])

IT04 = F('XX', 'Razón y revelación', 'Epistemología',
 'En «Dar\' ta\'arud» sostiene que la razón clara nunca contradice a la revelación bien establecida; cuando parecen chocar, lo concluyente prevalece, y los «cánones» de los teólogos ponen la razón por encima.',
 'Es su regla de conocimiento más citada. Incluye un pasaje donde compara el método de los teólogos con el credo cristiano.',
 ['dar'], FOOT,
 [
  Q('T3-03', es='«No concedemos que la división se limite a las cuatro clases que mencionaste, pues es posible decir que [[k:se da prioridad a lo racional unas veces y a lo transmitido otras]]: lo que sea concluyente tiene prioridad; si ambos son concluyentes, la contradicción es imposible; y si ambos son solo probables, [[k:tiene prioridad el más probable]].»',
     theme=['E'], clar='Es una réplica a la regla del teólogo al-Razi (que él resume). No es un resumen de toda su epistemología: dice que no hay solo cuatro opciones y que decide lo que sea concluyente, venga de donde venga.'),
  Q('T3-05', es='«Decimos una proposición general y universal: [[k:los textos establecidos del Mensajero nunca fueron contradichos por una razón clara]], cuanto menos puede ésta tener prioridad sobre ellos.»',
     theme=['E'], clar='Es su formulación propia. Restringe a «textos establecidos» y a «razón clara»; las contradicciones aparentes las atribuye a confusión («shubha») o a imaginación. Lectura (mía): la tesis se protege sola: si hay choque, por definición uno de los dos no era «clara» o «establecido».'),
  SP('dar', 'وهذا يشبه ما وضعته النصارى من أمانتهم', 'فالنصارى أقرب إلى تعظيم الأنبياء والرسل من هؤلاء',
     es='«Esto se parece a lo que establecieron los cristianos con su credo (amana), que hicieron el credo de su fe y al que sometieron los textos de la Torá y del Evangelio. Pero en ese credo se apoyaron en lo que entendieron de los textos de los profetas o en lo que les llegó de ellos, y se equivocaron en la comprensión o en creer al transmisor, como todos los que se equivocan entre quienes argumentan con lo transmitido […]. En cambio estos [los teólogos y filósofos] fijaron sus reglas según lo que vieron con su razón, y se equivocaron en la opinión y en la razón: [[k:los cristianos están más cerca de honrar a los profetas y mensajeros que ellos]].»',
     theme=['E', 'C'], clar='Pasaje poco citado: compara a los teólogos musulmanes del kalam con el credo cristiano. Dice que los cristianos erraron en la comprensión o en el transmisor, pero que están más cerca de honrar a los profetas que quienes someten la revelación a la razón. Es una comparación retórica, no una descripción de su doctrina.'),
 ])

IT05 = F('XX', 'Fitra y «primera obligación»', 'Epistemología',
 'Para Ibn Taymiyya, el conocimiento de Dios es innato (fitra): la reflexión no es la primera obligación, y los mensajeros vinieron a completar la fitra, no a sustituirla por pruebas.',
 'Es su alternativa a las pruebas racionales de los teólogos (la prueba de los accidentes y la «novedad» del mundo).',
 ['maj', 'dar'], FOOT,
 [
  Q('T3-12', es='«Esta aleya también indica que [[k:la reflexión no es la primera obligación]]: lo primero que Dios ordenó a su Profeta fue «¡Lee en el nombre de tu Señor!» (96:1); no le dijo «reflexiona y razona hasta conocer al Creador». Y así fue lo primero que se transmitió de esta sura: los destinatarios fueron interpelados por esta aleya antes que por nada, y no se les ordenó en ella reflexionar ni razonar.»',
     theme=['E'], clar='Rechaza la tesis de que lo primero que debe hacer el creyente es razonar para conocer a Dios. Argumenta desde el orden de la primera revelación (Corán 96:1).'),
  Q('T3-08', es='«[…] pueden dejar a la gente en la duda sobre lo que ya conocen por la fitra necesaria; y los Mensajeros —la paz y las bendiciones sean con ellos— fueron enviados [[k:para completar la fitra y consolidarla, no para corromperla ni alterarla]].»',
     theme=['E'], clar='El sujeto implícito son los filósofos y los teólogos del pasaje anterior. Es una tesis de principio: la razón teórica puede sembrar dudas sobre lo que la fitra da por sabido.'),
  Q('T3-11', es='«[…] así como el método de argumentar desde la aparición de las cosas originadas hasta la existencia del Creador [[k:es un método innato y necesario]] —lo mejor que tienen ellos; es más, no tienen otro método correcto—, pero introdujeron en él tanto desorden y corrupción como saben los investigadores y críticos.»',
     theme=['E'], start='كما أن طريقة الاستدلال بحدوث المحدثات', clar='Acepta la inferencia de lo originado al Creador como innata y necesaria; critica la versión de los teólogos (con accidentes e infinito regresivo). Ojo: no rechaza la conclusión (que el mundo tiene Creador) sino el modo de probarla.',
     christian=dict(head='Valoración de especialistas (secundaria)', txt='Rayan y Baraijia (2026, p. 371) sostienen que su doctrina de la fitra es [[k:inconsistente]]: a veces innata, a veces capacidad, a veces adquirida por los sentidos, y que acaba en una fitra sensorial que niega el conocimiento innato previo.', src='Sobhi Rayan e Isa Baraijia, «Doctrine of Fitrah in the Thought of Ibn Taymiyyah», Journal of Islamic Thought and Civilization 16(1), 2026 (acceso abierto; leído por un investigador, no por mí en detalle).')),
 ])

IT06 = F('XX', 'Contra la lógica griega', 'Epistemología',
 'En «Al-Radd \'ala al-mantiqiyyin» rechaza la definición aristotélica y el silogismo como fuentes necesarias de conocimiento; defiende la analogía (tamthil) y el conocimiento por signos.',
 'Es su crítica a la «lógica de Aristóteles», que afecta a cómo se establecen las pruebas de la existencia de Dios y de la profecía.',
 ['radd'], FOOT,
 [
  Q('T4-E03', es='«Si la indicación del nombre sobre lo nombrado va precedida de la concepción de lo nombrado, [[k:la indicación de la definición sobre lo definido debe ir precedida de la concepción de lo definido]]. Y si tanto lo definido como lo nombrado se conciben sin el nombre y sin la definición […], es imposible que se conciban las cosas definidas por la mera definición, [[k:como es imposible concebir las cosas nombradas por los meros nombres]]. Y esto es lo que se quería demostrar.»',
     theme=['E'], clar='Es su primer argumento contra la definición («hadd») de los lógicos: una definición solo significa como un nombre, y presupone la concepción de lo que se quiere definir; por tanto no la produce.'),
  Q('T4-E07', es='«[…] si conocen esa proposición universal por analogía entre lo ausente y lo presente —que el caso de una cosa es el de su semejante: si sabemos que este fuego quema, sabemos que el fuego ausente quema, por ser su semejante—, entonces se dice: esto es argumentar por [[k:analogía (qiyas al-tamthil), que ellos pretenden que solo da opinión, no certeza]]. Y si llegaron a la proposición universal por la analogía, [[k:volvieron, para la certeza, a aquello que dicen que solo da opinión]].»',
     theme=['E'], start='فان عرفوها', clar='Es un dilema: si las premisas universales de su demostración se conocen por analogía, su propia tesis (que la analogía solo da opinión) socava la certeza de su demostración; si se conocen de otro modo, queda refutado que todo conocimiento necesite silogismo. Lectura (mía): él usa también dilemas y reducciones al absurdo; Zwirahn (2018, pp. 75–76) dice que critica a los teólogos por usar la lógica y la emplea en su polémica contra los cristianos.'),
  Q('T4-E13', es='«Establecer el conocimiento del Creador y de las profecías [[k:no depende de ningún silogismo]]: se conoce por los signos (ayat) que indican algo concreto, sin generalidad, y se alcanza por el conocimiento necesario, que no requiere especulación. Y lo que se obtiene por el silogismo universal es como lo que se obtiene por la analogía: algo general con lo cual [[k:no se conoce lo que es propio del Señor ni lo propio del Mensajero]] si no se le añade otro conocimiento.»',
     theme=['E'], clar='Resume su postura positiva: la prueba de Dios y de la profecía son los «signos» concretos y el conocimiento necesario, no un silogismo con premisas universales.'),
 ])
